  function ConvertTo-AgyStdin {
      param([string]$Prompt)
      $o = [pscustomobject]@{ event = 'user'; message = [pscustomobject]@{ content = $Prompt } }
      return ((ConvertTo-Json -InputObject $o -Compress -Depth 5) + "`n")
